  },
  {
    "id": "Q5",
    "question": "Which information systems are used to log, track, or manage sample transfers and disposal requests throughout this workflow?"
  },
  {
    "id": "Q6",
    "question": "Are there defined time limits or service-level expectations for how quickly a transfer must be completed after it is requested, or for how long a disposal request should take from submission to completion?"
  }
]
